window.docContents[114].resolve({"/Hoare/#Hoare-Logic--Hoare___-Hoare-Logic___-Part-I--Proof-Rules--Sequencing":{"contents":"If command c1 takes any state where P holds to a state where\nQ holds, and if c2 takes any state where Q holds to one\nwhere R holds, then doing c1 followed by c2 will take any\nstate where P holds to one where R holds:\n\n {{ P }} c1 {{ Q }}\n {{ Q }} c2 {{ R }}\n----------------------  (hoare_seq)\n{{ P }} c1;c2 {{ R }}\n\n\ntheorem hoare_seq (P Q R : Assertion) (c1 c2 : Com)\n    (h1 : {{ Q }} ~c2 {{ R }}) (h2 : {{ P }} ~c1 {{ Q }}) :\n    {{ P }} ~c1 ~c2 {{ R }} := by\n  intro st st' h12 pre\n  inversion h12 with\n  | seq st'' hc1 hc2 =>\n    exact h1 _ _ hc2 (h2 _ _ hc1 pre)\n\n\n\n\n","context":"Hoare Logic\u0009Hoare: Hoare Logic, Part I\u0009Proof Rules","header":"4.4.2. Sequencing","id":"/Hoare/#Hoare-Logic--Hoare___-Hoare-Logic___-Part-I--Proof-Rules--Sequencing"}});